<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,shallowRef,watch} from 'vue'
import {getSession} from './api'
import {localManagement,desktopManagement,operatorRequest,saveSettings,savePair,saveCustom,deleteCustom,fetchCustomModels,type Configuration,type Pair} from './systemManagement'
const config=shallowRef<Configuration>(),pair=shallowRef<Pair>(),busy=ref(false),uncertain=ref(false),error=ref(''),message=ref(''),preset=ref(''),base=ref(''),model=ref(''),key=ref(''),remember=ref(true),confirmed=ref(false),keys=ref({A:'',B:''}),pairPresets=ref({A:'',B:''}),pairConfirmed=ref({A:false,B:false}),label=ref(''),customNote=ref(''),customConsent=ref(false),deleteName=ref('')
const local=computed(localManagement),selected=computed(()=>config.value?.model_presets.find(p=>p.id===preset.value))
const desktop=computed(desktopManagement)
const modelChoices=ref<string[]>([]),catalogModel=ref('')
watch(base,()=>{modelChoices.value=[];catalogModel.value=''})
async function queryModels(){if(busy.value||!desktop.value)return;const token=revision,origin=base.value;busy.value=true;error.value='';modelChoices.value=[];catalogModel.value='';try{const data=await fetchCustomModels(origin,key.value);if(alive&&token===revision&&base.value===origin){modelChoices.value=data.models;message.value=`已读取${data.models.length}个模型；请核对其图片输入能力。`}}catch(e){if(alive&&token===revision)error.value=(e as Error).message}finally{key.value='';if(alive&&token===revision)busy.value=false}}
let revision=0,alive=true
function clearSecrets(){key.value='';keys.value={A:'',B:''}}
function changed(){confirmed.value=false;customConsent.value=false;deleteName.value='';clearSecrets()}
function choose(){const p=selected.value;base.value=p?.base_url||'';model.value=p?.model||'';label.value=p?.user_defined?p.label:'';customNote.value=p?.user_defined?p.note||'':'';changed()}
async function read(){const token=++revision;busy.value=true;config.value=undefined;pair.value=undefined;uncertain.value=false;error.value='';clearSecrets();confirmed.value=false;pairConfirmed.value={A:false,B:false};customConsent.value=false;deleteName.value='';try{const [c,p]=await Promise.all([operatorRequest<Configuration>('/api/status'),operatorRequest<Pair>('/api/dual-review/status')]);if(!alive||token!==revision)return;config.value=c;pair.value=p;preset.value=c.model_preset;base.value=c.base_url;model.value=c.model;pairPresets.value={A:p.preset_a,B:p.preset_b}}catch(e){if(alive&&token===revision)error.value=(e as Error).message}finally{if(alive&&token===revision)busy.value=false}}
async function write(action:()=>Promise<unknown>){if(busy.value||uncertain.value)return;const token=revision;busy.value=true;error.value='';message.value='';try{await action();if(!alive||token!==revision)return;message.value='配置已保存；未调用模型。';await read()}catch{if(alive&&token===revision){error.value='保存结果未能确认，请先刷新配置核实；不会自动重试。';uncertain.value=true}}finally{clearSecrets();if(alive)busy.value=false}}
onMounted(read);onUnmounted(()=>{alive=false;revision++;clearSecrets();config.value=undefined;pair.value=undefined})
</script>
<template><section aria-label="模型配置管理"><h3>模型配置管理</h3><p>保存配置不会测试调用模型。Key仅在保存请求中提交，提交后清空输入框；已有Key不回显、不写浏览器存储。云端主模型沿用服务器预设；管理员可分别选择双评模型并替换服务器Key。</p><button @click="read" :disabled="busy">刷新模型配置</button><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
 <template v-if="config"><form @submit.prevent="write(()=>saveSettings(preset,base,model,key,remember,confirmed))"><fieldset :disabled="busy||uncertain"><legend>主模型</legend><label for="system-model-preset">主模型预设</label><select id="system-model-preset" v-model="preset" @change="choose"><option value="">请选择</option><option v-for="p in config.model_presets" :key="p.id" :value="p.id">{{ p.label }}</option></select><template v-if="local"><label>接口地址<input v-model="base" maxlength="500" @input="confirmed=false;customConsent=false"></label><label>模型ID<input v-model="model" maxlength="200" @input="confirmed=false;customConsent=false"></label><label>主模型API Key（留空沿用现有）<input v-model="key" type="password" autocomplete="off" maxlength="500" @input="confirmed=false"></label><label class="check"><input type="checkbox" v-model="remember" @change="confirmed=false">使用现有本机安全存储记住Key；取消则仅本次运行</label></template><p>现有Key：{{ config.api_key_configured?'已就绪':'未就绪' }}；{{ config.api_key_session_only?'仅本次运行':'按现有安全存储配置' }}</p><label class="check"><input type="checkbox" v-model="confirmed">确认修改主模型配置</label><button :disabled="!confirmed||!preset||(!local&&!config.server_model_selection_enabled)">保存主模型配置</button></fieldset></form>
 <template v-if="pair"><article v-for="side in (['A','B'] as const)" :key="side" class="point-record"><form @submit.prevent="write(()=>savePair(side,pairPresets[side],keys[side],pairConfirmed[side]))"><fieldset :disabled="busy||uncertain"><legend>AI-{{ side }}独立配置</legend><label :for="'pair-'+side">AI-{{ side }}模型</label><select :id="'pair-'+side" v-model="pairPresets[side]" @change="pairConfirmed[side]=false;keys[side]=''"><option v-for="p in pair.available_models" :key="p.id" :value="p.id">{{ p.label }}</option></select><label>AI-{{ side }} API Key（留空沿用）<input v-model="keys[side]" type="password" maxlength="500" autocomplete="off" @input="pairConfirmed[side]=false"></label><p>{{ (side==='A'?pair.configured_a:pair.configured_b)?'配置已就绪':'配置未就绪' }}</p><label class="check"><input type="checkbox" v-model="pairConfirmed[side]">确认修改AI-{{ side }}配置</label><button :disabled="!pairConfirmed[side]">保存AI-{{ side }}配置</button></fieldset></form></article><p v-if="!local">云端Key只保存于服务器受限目录，不回显。留空只沿用所选服务商已有Key，不会把其他服务商Key用于新模型。</p></template>
 <fieldset v-if="desktop" :disabled="busy||uncertain"><legend>自定义模型预设</legend><p>查询仅发送所填接口及当前输入的主模型Key，不沿用已保存Key，也不会调用批改模型。</p><button type="button" @click="queryModels" :disabled="!base">确认查询模型列表</button><label v-if="modelChoices.length">上游模型列表<select aria-label="上游模型列表" v-model="catalogModel" @change="model=catalogModel;customConsent=false;confirmed=false"><option value="">请选择</option><option v-for="id in modelChoices" :key="id" :value="id">{{ id }}</option></select></label><p>使用上方接口地址和模型ID保存自定义预设；仅保存目录，不会启用或调用模型。</p><label>自定义预设名称<input v-model="label" maxlength="100" @input="customConsent=false"></label><label>自定义预设备注<textarea v-model="customNote" @input="customConsent=false"></textarea></label><label class="check"><input type="checkbox" v-model="customConsent">确认保存自定义预设</label><button @click="write(()=>saveCustom(selected?.user_defined?preset:'',label,base,model,customNote,customConsent))" :disabled="!customConsent||!label||!base||!model">保存自定义预设</button><template v-if="selected?.user_defined"><label>输入所选预设名称确认删除<input v-model="deleteName"></label><button @click="selected&&write(()=>deleteCustom(selected!,deleteName))" :disabled="deleteName!==selected.label">删除所选自定义预设</button></template></fieldset>
 </template>
</section></template>
